## Retry decorator with exponential backoff + jitter

Dependency-free (stdlib only), works on Python 3.7+.

```python
import functools
import random
import time


def retry(max_attempts=3, base_delay=0.1, backoff_factor=2.0,
          max_delay=None, jitter=True, exceptions=(Exception,)):
    """Retry a function when it raises one of `exceptions`.

    max_attempts   : total number of calls (1 = no retry)
    base_delay     : delay before the first retry, in seconds
    backoff_factor : multiplier applied per attempt (2.0 = 0.1, 0.2, 0.4, ...)
    max_delay      : optional cap on the computed delay
    jitter         : if True, use "full jitter": uniform(0, delay)
    exceptions     : exception type or tuple of types that trigger a retry
    """
    if max_attempts < 1:
        raise ValueError("max_attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 0
            while True:
                attempt += 1
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt >= max_attempts:
                        raise  # re-raise last error, original traceback intact
                    delay = base_delay * (backoff_factor ** (attempt - 1))
                    if max_delay is not None:
                        delay = min(delay, max_delay)
                    if jitter:
                        delay = random.uniform(0, delay)
                    time.sleep(delay)
        return wrapper
    return decorator
```

**Semantics worth noting**

- `max_attempts` counts *total* calls, so `max_attempts=3` means 1 initial call + 2 retries.
- Exceptions not listed in `exceptions` propagate immediately — no sleep, no retry.
- No sleep occurs after the final failed attempt.
- Full jitter (`uniform(0, delay)`) can never produce a negative delay and spreads out concurrent retries.

## Runnable test

Fast and deterministic: `time.sleep` is patched out and jitter is disabled where timing is asserted.

```python
import unittest
from unittest.mock import patch


class RetryTest(unittest.TestCase):
    @patch("time.sleep", return_value=None)
    def test_retries_then_succeeds(self, mock_sleep):
        calls = {"n": 0}

        @retry(max_attempts=4, base_delay=0.01, backoff_factor=2.0,
               jitter=False, exceptions=(ValueError,))
        def flaky():
            calls["n"] += 1
            if calls["n"] < 3:
                raise ValueError("boom")
            return "ok"

        self.assertEqual(flaky(), "ok")
        self.assertEqual(calls["n"], 3)                      # 2 failures + 1 success
        self.assertEqual(mock_sleep.call_count, 2)           # one sleep per retry
        self.assertEqual([c.args[0] for c in mock_sleep.call_args_list],
                         [0.01, 0.02])                       # exponential growth

    @patch("time.sleep", return_value=None)
    def test_exhausts_and_reraises(self, mock_sleep):
        @retry(max_attempts=3, base_delay=0.01, jitter=False, exceptions=(ValueError,))
        def always_fails():
            raise ValueError("nope")

        with self.assertRaises(ValueError):
            always_fails()
        self.assertEqual(mock_sleep.call_count, 2)           # no sleep after last try

    @patch("time.sleep", return_value=None)
    def test_unlisted_exception_not_retried(self, mock_sleep):
        @retry(max_attempts=3, exceptions=(ValueError,))
        def wrong_error():
            raise TypeError("different")

        with self.assertRaises(TypeError):
            wrong_error()
        mock_sleep.assert_not_called()

    def test_preserves_metadata(self):
        @retry()
        def documented():
            """docstring"""

        self.assertEqual(documented.__name__, "documented")
        self.assertEqual(documented.__doc__, "docstring")


if __name__ == "__main__":
    unittest.main()
```

## Usage

```python
import urllib.error

@retry(max_attempts=5, base_delay=0.5, max_delay=10,
       exceptions=(urllib.error.URLError, TimeoutError))
def fetch(url):
    ...
```

For `async def` functions, use the same structure but `await asyncio.sleep(delay)` inside an `async def wrapper`.

